#!/usr/bin/env python3
"""Compute ground truth for CSX-272_Q1."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from statistics import mean
from typing import Any


TASK_ID = "CSX-272_Q1"
EVENT_ID = "CSX-272"
TARGET_FAMILY = "queensland_la_nina_rainfall_load_score_ledger"
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = Path(__file__).resolve().parent / "computed_gt.json"

ONI_SEASONS = (("SON", 2010), ("OND", 2010), ("NDJ", 2010), ("DJF", 2011))
SOI_MONTHS = ((2010, 9), (2010, 10), (2010, 11), (2010, 12), (2011, 1), (2011, 2))


def read_json(rel_path: str) -> Any:
    with (PACKAGE / rel_path).open("r", encoding="utf-8") as f:
        return json.load(f)


def read_text(rel_path: str) -> str:
    return (PACKAGE / rel_path).read_text(encoding="utf-8", errors="ignore")


def manifest_count() -> int:
    with (PACKAGE / "metadata" / "files.csv").open("r", encoding="utf-8-sig", newline="") as f:
        return sum(1 for _ in csv.DictReader(f))


def cpc_oni_values() -> list[dict[str, float | int | str]]:
    rows: dict[tuple[str, int], dict[str, float | int | str]] = {}
    for line in read_text("data/physical_hazard/physical_hazard_006_NOAA_CPC_ONI_ASCII.txt").splitlines():
        parts = line.split()
        if len(parts) == 4 and parts[1].isdigit():
            key = (parts[0], int(parts[1]))
            rows[key] = {
                "season": parts[0],
                "year": int(parts[1]),
                "total": float(parts[2]),
                "anomaly": float(parts[3]),
            }
    return [rows[key] for key in ONI_SEASONS]


def soi_values() -> list[float]:
    yearly: dict[int, list[float]] = {}
    for line in read_text("data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data").splitlines():
        parts = line.split()
        if len(parts) == 13 and parts[0].isdigit():
            yearly[int(parts[0])] = [float(value) for value in parts[1:]]
    return [yearly[year][month - 1] for year, month in SOI_MONTHS]


def grid_precipitation() -> list[dict[str, float | str]]:
    specs = [
        (
            "era5_land",
            "data/physical_hazard/physical_hazard_011_ERA5-Land_hourly_aggregate_stats.json",
            "precipitation_sum_mm_mean",
            "precipitation_sum_mm_max",
        ),
        (
            "gpm_imerg",
            "data/physical_hazard/physical_hazard_012_GPM_IMERG_V07_event_accumulated_precipitation.json",
            "gpm_event_precip_mm_mean",
            "gpm_event_precip_mm_max",
        ),
        (
            "chirps",
            "data/physical_hazard/physical_hazard_013_CHIRPS_daily_event_accumulated_precipitation.json",
            "chirps_event_precip_mm_mean",
            "chirps_event_precip_mm_max",
        ),
    ]
    rows: list[dict[str, float | str]] = []
    for name, rel_path, mean_key, max_key in specs:
        stats = read_json(rel_path)["stats"]
        doc = read_json(rel_path)
        mean_mm = float(stats[mean_key])
        max_mm = float(stats[max_key])
        rows.append(
            {
                "name": name,
                "start": doc.get("start"),
                "end": doc.get("end"),
                "mean_mm": mean_mm,
                "max_mm": max_mm,
                "max_to_mean_ratio": max_mm / mean_mm,
            }
        )
    return rows


def rounded(value: float) -> float:
    return round(value, 2)


def build_result() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    anchor = read_json("data/event_reports/event_reports_002_Locked_event_anchor_2010-2011_La_Nina_and_Queensland_floods.json")
    oni_rows = cpc_oni_values()
    soi = soi_values()
    grids = grid_precipitation()

    oni_anomalies = [float(row["anomaly"]) for row in oni_rows]
    grid_means = [float(row["mean_mm"]) for row in grids]
    grid_maxima = [float(row["max_mm"]) for row in grids]
    ratios = [float(row["max_to_mean_ratio"]) for row in grids]

    inputs = {
        "oni_cold_n": sum(1 for value in oni_anomalies if value <= -1.0),
        "oni_mean": mean(oni_anomalies),
        "soi_pos_n": sum(1 for value in soi if value > 0),
        "soi_mean": mean(soi),
        "grid_mean_mm": mean(grid_means),
        "grid_max_mm": max(grid_maxima),
        "ratio_mean": mean(ratios),
    }
    components = {
        "oni_count": 20 * (inputs["oni_cold_n"] / 4),
        "oni_mean": 20 * min(abs(inputs["oni_mean"]) / 1.5, 1),
        "soi_count": 15 * (inputs["soi_pos_n"] / 6),
        "soi_mean": 10 * min(inputs["soi_mean"] / 4, 1),
        "grid_mean": 15 * min(inputs["grid_mean_mm"] / 120, 1),
        "grid_max": 10 * min(inputs["grid_max_mm"] / 200, 1),
        "ratio": 10 * min(inputs["ratio_mean"] / 1.5, 1),
    }
    answer = rounded(sum(components.values()))
    rounded_inputs = {
        "climate_period": "2010-09-01_to_2011-02-28",
        "precip_evidence_window": f"{grids[0]['start']}_to_{grids[0]['end']}",
        "oni_cold_n": inputs["oni_cold_n"],
        "oni_mean": rounded(inputs["oni_mean"]),
        "soi_pos_n": inputs["soi_pos_n"],
        "soi_mean": rounded(inputs["soi_mean"]),
        "grid_mean_mm": rounded(inputs["grid_mean_mm"]),
        "grid_max_mm": rounded(inputs["grid_max_mm"]),
        "ratio_mean": rounded(inputs["ratio_mean"]),
    }
    rounded_components = {key: rounded(value) for key, value in components.items()}

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": {
                "score": answer,
                **rounded_inputs,
            },
            "derivation": "The score is 20.00 + 20.00 + 15.00 + 9.08 + 14.76 + 10.00 + 9.74 = 98.58.",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "ONI ledger",
                    "points": 4,
                    "description": "Parses the four ONI seasons and computes the cold-season count plus mean anomaly.",
                },
                {
                    "name": "SOI ledger",
                    "points": 4,
                    "description": "Parses the six SOI months and computes the positive-month count plus mean value.",
                },
                {
                    "name": "Rainfall ledger",
                    "points": 4,
                    "description": "Extracts gridded precipitation means, maxima, max-to-mean ratios, and the declared precipitation evidence window from all three summaries.",
                },
                {
                    "name": "Score arithmetic",
                    "points": 5,
                    "description": "Applies every denominator and cap to obtain 98.58 within 0.02.",
                },
                {
                    "name": "Auditable derivation",
                    "points": 3,
                    "description": "Shows enough intermediate arithmetic to reproduce the numeric result.",
                },
            ],
        },
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "period": f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}",
            "region": event["region"],
            "scale": event["scale"],
        },
        "key_values": {
            "manifest_file_count": manifest_count(),
            "oni_rows": [
                f"{row['season']} {row['year']} {rounded(float(row['anomaly']))}"
                for row in oni_rows
            ],
            "soi_values": [rounded(value) for value in soi],
                "grid_sources": [
                {
                    "name": row["name"],
                    "window": f"{row['start']}_to_{row['end']}",
                    "mean_mm": rounded(float(row["mean_mm"])),
                    "max_mm": rounded(float(row["max_mm"])),
                    "ratio": rounded(float(row["max_to_mean_ratio"])),
                }
                for row in grids
            ],
            "score_terms": rounded_components,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "metadata/files.csv",
                "data/event_reports/event_reports_002_Locked_event_anchor_2010-2011_La_Nina_and_Queensland_floods.json",
                "data/physical_hazard/physical_hazard_006_NOAA_CPC_ONI_ASCII.txt",
                "data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data",
                "data/physical_hazard/physical_hazard_011_ERA5-Land_hourly_aggregate_stats.json",
                "data/physical_hazard/physical_hazard_012_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_013_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
        },
    }


def main() -> None:
    result = build_result()
    OUT.write_text(json.dumps(result, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
